// One-bit shift register with four DFFs, where each DFF is a dedicated
// Flip-Flop, independent of the others.
module TopModule(
    input  clk,
    input  resetn,
    input  in,
    output reg out
);
    reg [3:0] sr;
    always @(posedge clk) begin
        if (!resetn) begin
            sr <= 4'b0;
            out <= 1'b0;
        end else begin
            sr <= {sr[2:0], in};
            out <= sr[3];
        end
    end
endmodule

